export var LIBR=0, LIB_RULES={"Ability Check":{"c":"Rule","d":"A [[D20 Test]] where you use an ability, or a skill tied to an ability, to overcome a challenge."},"Ability Score and Modifier":{"c":"Rule","d":"Every creature has six ability scores: Strength, Dexterity, Constitution, Intelligence, Wisdom and Charisma. Each score gives a modifier. Add it to D20 Tests that use that ability, and whenever a rule tells you to."},"Action":{"c":"Rule","d":"On your turn you take one action, chosen from the standard actions or from special actions your features give you. The standard actions are [[Attack]], [[Dash]], [[Disengage]], [[Dodge]], [[Help]], [[Hide]], [[Influence]], [[Magic]], [[Ready]], [[Search]], [[Study]] and [[Utilize]]."},"Adventure":{"c":"Game Term","d":"A story told through a series of encounters."},"Alignment":{"c":"Rule","d":"A broad label for a creature's ethics and outlook. It pairs a moral axis (good, neutral, evil) with an attitude toward order (lawful, neutral, chaotic), which gives nine combinations such as Lawful Good or Neutral Evil."},"Ally":{"c":"Rule","d":"A creature is your ally if it is in your party, is your friend, fights on your side, or is named your ally by a rule or the DM."},"Area of Effect":{"c":"Rule","d":"Many spells and features affect an area shaped as a [[Cone]], [[Cube]], [[Cylinder]], [[Emanation]], [[Line]] or [[Sphere]]. The area starts at a point of origin. A location is left out of the area if every straight line from the origin to it is blocked, and a line counts as blocked only by something that gives [[Cover]]. If the creator picks an unseen point with a barrier in the way, the origin forms on the near side of the barrier."},"Armor Training":{"c":"Rule","d":"Training lets you use a category of armor without penalty. Wearing Light, Medium or Heavy armor without training gives you Disadvantage on D20 Tests that use Strength or Dexterity and stops you from casting spells. Using a Shield without training means you get no AC bonus from it."},"Attack Roll":{"c":"Rule","d":"A [[D20 Test]] made to attack with a weapon, an [[Unarmed Strike]] or a spell."},"Attitude":{"c":"Rule","d":"A monster starts with an attitude toward player characters: [[Friendly]], [[Hostile]] or [[Indifferent]]."},"Attunement":{"c":"Rule","d":"Some magic items work only after a creature bonds with them. A creature can be attuned to at most three magic items at once."},"Breaking Objects":{"c":"Rule","d":"Attacks and some spells can harm objects. **Armor Class** by material: cloth, paper or rope 11. Crystal, glass or ice 13. Wood 15. Stone 17. Iron or steel 19. Mithral 21. Adamantite 23. **Hit Points** for Large or smaller objects, fragile or resilient: Tiny 2 (1d4) or 5 (2d4). Small 3 (1d6) or 10 (3d6). Medium 4 (1d8) or 18 (4d8). Large 5 (1d10) or 27 (5d10). An object is destroyed at 0 Hit Points. Split a Huge or Gargantuan object into Large or smaller sections and track each one. The DM decides whether losing a part brings down the whole. **Damage types.** Objects are immune to Poison and Psychic damage. The DM may rule that other types work better or worse, such as Bludgeoning to smash and Fire against paper. Big objects such as castle walls often have a [[Damage Threshold]]. **No ability scores.** An object can't make ability checks and fails every saving throw. The DM may let a creature break a very fragile object automatically with the [[Attack]] or [[Utilize]] action."},"Bright Light":{"c":"Vision and Light","d":"Normal illumination."},"Burrow Speed":{"c":"Movement","d":"Lets a creature move through sand, earth, mud or ice. It can't tunnel through solid rock unless a trait says it can."},"Campaign":{"c":"Game Term","d":"A series of adventures."},"Cantrip":{"c":"Spellcasting","d":"A level 0 spell. You cast it without a spell slot."},"Challenge Rating":{"c":"Rule","d":"A number that sums up how dangerous a monster is to a party of four player characters. A CR above the characters' level means real danger and a lower CR means little threat. Party size and circumstances change that a lot. The Dungeon Master's Guide explains how DMs use it."},"Character Sheet":{"c":"Game Term","d":"A paper or digital record of your character's information."},"Climb Speed":{"c":"Movement","d":"Used instead of your Speed to move on vertical surfaces without paying the extra movement for [[Climbing]]."},"Climbing":{"c":"Movement","d":"Each foot of movement costs 1 extra foot, or 2 extra in [[Difficult Terrain]]. A Climb Speed removes the extra cost. The DM may call for a DC 15 Strength (Athletics) check on a slippery surface or one with few handholds."},"Condition":{"c":"Rule","d":"A temporary state. Each condition says how it affects its target and how it ends. A condition does not stack with itself, except [[Exhaustion]]. The conditions are [[Blinded]], [[Charmed]], [[Deafened]], [[Exhaustion]], [[Frightened]], [[Grappled]], [[Incapacitated]], [[Invisible]], [[Paralyzed]], [[Petrified]], [[Poisoned]], [[Prone]], [[Restrained]], [[Stunned]] and [[Unconscious]]."},"Cone":{"c":"Area of Effect","d":"An area that spreads from a point of origin in a direction its creator picks. Its width at any point equals that point's distance from the origin, so it is 15 feet wide 15 feet out. The effect gives the maximum length. The origin is not in the area unless the creator says so."},"Cover":{"c":"Rule","d":"Cover protects a target from what lies behind an obstacle. **Half Cover:** +2 to AC and Dexterity saving throws. **Three-Quarters Cover:** +5 to AC and Dexterity saving throws. **Total Cover:** the target can't be targeted directly. With several degrees of cover, only the strongest applies."},"Crawling":{"c":"Movement","d":"Each foot of movement costs 1 extra foot, or 2 extra in [[Difficult Terrain]]."},"Creature":{"c":"Game Term","d":"Any being in the game, player characters included."},"Creature Type":{"c":"Rule","d":"Every creature has a type tag, and most player characters are Humanoid. The types are Aberration, Beast, Celestial, Construct, Dragon, Elemental, Fey, Fiend, Giant, Humanoid, Monstrosity, Ooze, Plant and Undead. Types have no rules of their own, but some rules treat certain types differently."},"Critical Hit":{"c":"Rule","d":"Rolling a 20 on the d20 for an attack roll is a Critical Hit. It hits whatever the modifiers or the target's AC. Roll all of the attack's damage dice twice and add them together, then add the modifiers."},"Cube":{"c":"Area of Effect","d":"An area with sides of a length the effect gives. The point of origin sits anywhere on one face. The origin is not in the area unless the creator says so."},"Curses":{"c":"Rule","d":"Some effects curse a creature or an object, and the effect defines what the curse does. Remove Curse, Greater Restoration and other magic that ends curses can remove it."},"Cylinder":{"c":"Area of Effect","d":"An area with a circular base of a given radius and a given height. The point of origin is the center of the top or bottom circle and is inside the area."},"D20 Test":{"c":"Rule","d":"The three main d20 rolls of the game: [[Ability Check]], [[Attack Roll]] and [[Saving Throw]]. Anything that affects D20 Tests affects all three. The DM decides when a D20 Test is needed."},"Damage":{"c":"Rule","d":"Harm that makes a creature or object lose Hit Points."},"Damage Roll":{"c":"Rule","d":"A die roll, plus modifiers, that deals damage to a target."},"Damage Threshold":{"c":"Rule","d":"A creature or object with a damage threshold is immune to damage unless a single attack or effect deals at least that much. Then it takes all of that damage. With a threshold of 10, 9 damage does nothing and 11 damage deals 11."},"Damage Types":{"c":"Rule","d":"Attacks and harmful effects deal different types of damage. The types have no rules of their own, but rules such as [[Resistance]] use them. **Acid:** corrosive liquids, digestive enzymes. **Bludgeoning:** blunt objects, constriction, falling. **Cold:** freezing water, icy blasts. **Fire:** flames, unbearable heat. **Force:** pure magical energy. **Lightning:** electricity. **Necrotic:** life-draining energy. **Piercing:** fangs, puncturing objects. **Poison:** toxic gas, venom. **Psychic:** mind-rending energy. **Radiant:** holy energy, searing radiation. **Slashing:** claws, cutting objects. **Thunder:** concussive sound."},"Darkness":{"c":"Vision and Light","d":"An area of Darkness is [[Heavily Obscured]]."},"Dead":{"c":"Rule","d":"A dead creature has 0 Hit Points and can't regain any until magic such as Raise Dead or Revivify brings it back. The spirit knows who casts the spell and can refuse. It has left for the Outer Planes, so reviving the creature means calling it back. The revival effect sets the creature's current Hit Points. Unless stated otherwise, it returns with the conditions, magical contagions and curses it had, if their durations still run. It returns with one fewer level of Exhaustion if it had any, and it is no longer attuned to magic items."},"Difficult Terrain":{"c":"Movement","d":"Every foot of movement in the space costs 1 extra foot, so moving 5 feet costs 10. It does not stack. A space is Difficult Terrain if it holds a creature that isn't Tiny or your ally, furniture sized for your size or larger, heavy snow, ice, rubble or undergrowth, liquid between shin- and waist-deep, a narrow opening sized for a creature one size smaller than you, or a slope of 20 degrees or more."},"Difficulty Class":{"c":"Rule","d":"The target number for an [[Ability Check]] or [[Saving Throw]]."},"Dim Light":{"c":"Vision and Light","d":"An area of Dim Light is [[Lightly Obscured]]."},"Emanation":{"c":"Area of Effect","d":"An area that extends in all directions from a creature or object, out to the distance the effect gives. It moves with its origin unless the effect is instantaneous or stationary. The origin is not in the area unless the creator says so."},"Encounter":{"c":"Game Term","d":"A scene in an adventure that belongs to at least one of the three pillars: social interaction, exploration or combat."},"Enemy":{"c":"Rule","d":"A creature is your enemy if it fights you, actively tries to harm you, or is named your enemy by a rule or the DM."},"Experience Points":{"c":"Rule","d":"Characters earn Experience Points (XP) by overcoming challenges and finishing adventures, as the DM awards them. When the total passes a threshold, the character gains a level."},"Expertise":{"c":"Rule","d":"Doubles your [[Proficiency Bonus]] on ability checks with a skill you are proficient in, unless another feature already doubles it. You gain it in one skill you are proficient in, and never twice in the same skill."},"Fly Speed":{"c":"Movement","d":"Lets a creature travel through the air. With a Fly Speed you stay aloft until you land, fall or die."},"Flying":{"c":"Movement","d":"While flying you fall if you have the [[Incapacitated]] or [[Prone]] condition or your Fly Speed drops to 0. If you can hover, you stay aloft in those cases."},"Friendly":{"c":"Attitude","d":"A Friendly creature views you well. You have Advantage on ability checks to influence it."},"Grappling":{"c":"Rule","d":"A creature can grapple another, usually with an [[Unarmed Strike]], and many monsters have special grapple attacks. However it starts, a success gives the target the [[Grappled]] condition. The grappler needs a free hand, or a tentacle, maw or other body part, and each part can hold only one creature at a time. To escape, the target uses an action for a Strength (Athletics) or Dexterity (Acrobatics) check against the grapple's escape DC. The grapple also ends if the grappler is [[Incapacitated]] or the target ends up beyond the grapple's range. The grappler can let go at any time with no action."},"Hazard":{"c":"Game Term","d":"An environmental danger."},"Healing":{"c":"Rule","d":"How you regain Hit Points."},"Heavily Obscured":{"c":"Vision and Light","d":"While trying to see something in a Heavily Obscured space, you have the [[Blinded]] condition."},"High Jump":{"c":"Movement","d":"You leap 3 feet plus your Strength modifier (minimum 0) if you moved at least 10 feet on foot right before. A standing High Jump covers half that. Each foot of the jump costs a foot of movement. During the jump you can reach up half your height above yourself, so your total reach equals the jump height plus 1½ times your height."},"Hostile":{"c":"Attitude","d":"A Hostile creature views you badly. You have Disadvantage on ability checks to influence it."},"Hover":{"c":"Movement","d":"Some creatures and effects can hover. Hovering while [[Flying]] keeps you from falling in some situations."},"Illusions":{"c":"Rule","d":"Spells sometimes create magical illusions. The effect says what the illusion does and which senses or minds it fools. An illusion in space is weightless and insubstantial, yet it looks affected by its surroundings as if real, unless the effect says otherwise. A visual illusion of a creature casts shadows and reflections, wind seems to move it, and an illusory sound echoes in an echoing space."},"Immunity":{"c":"Rule","d":"With Immunity to a damage type or a condition, it has no effect on you."},"Improvised Weapons":{"c":"Rule","d":"An object used as a makeshift weapon, such as broken glass, a table leg or a frying pan. A Simple or Martial weapon also counts if you use it against its design, for example a ranged weapon in melee or a thrown melee weapon without the Thrown property. **Proficiency:** don't add your Proficiency Bonus to the attack roll. **Damage:** 1d4 on a hit, of a type the DM finds fitting. **Range:** 20 feet, long range 60 feet when thrown. **Equivalents:** if it resembles a Simple or Martial weapon, the DM may treat it as that weapon, such as a table leg as a Club."},"Indifferent":{"c":"Attitude","d":"An Indifferent creature neither wants to help nor hinder you. It is a monster's default attitude."},"Jumping":{"c":"Movement","d":"A jump is a [[Long Jump]] (horizontal) or a [[High Jump]] (vertical)."},"Knocking Out a Creature":{"c":"Rule","d":"When a melee attack would reduce a creature to 0 Hit Points, you can leave it at 1 Hit Point instead. It becomes [[Unconscious]] and starts a Short Rest. It stays Unconscious until it regains Hit Points or someone uses an action to give first aid with a successful DC 10 Wisdom (Medicine) check."},"Lightly Obscured":{"c":"Vision and Light","d":"You have Disadvantage on Wisdom (Perception) checks to see something in a Lightly Obscured space."},"Line":{"c":"Area of Effect","d":"An area that runs from a point of origin in a straight path, with a length and a width the effect gives. The origin is not in the area unless the creator says so."},"Long Jump":{"c":"Movement","d":"You leap horizontally up to a number of feet equal to your Strength score if you moved at least 10 feet right before. A standing Long Jump covers half that. Each foot costs a foot of movement. If you land in [[Difficult Terrain]], you need a DC 10 Dexterity (Acrobatics) check or you fall [[Prone]]. This rule assumes the height of the jump doesn't matter, like crossing a stream or chasm. The DM may require a DC 10 Strength (Athletics) check to clear a low obstacle no taller than a quarter of the jump distance, such as a hedge. Otherwise you hit it."},"Magical Effect":{"c":"Rule","d":"An effect is magical if a spell, a magic item or a phenomenon the rules label as magical creates it."},"Monster":{"c":"Game Term","d":"A creature the DM controls, even a friendly one."},"Nonplayer Character":{"c":"Game Term","d":"A monster with a personal name and a distinct personality."},"Object":{"c":"Rule","d":"A distinct nonliving thing. Composite things such as buildings are made of several objects."},"Occupied Space":{"c":"Rule","d":"A space is occupied if a creature is in it or objects completely fill it."},"Per Day":{"c":"Rule","d":"If a rule gives a number of uses per day, you need a [[Long Rest]] to use it again once the uses run out."},"Player Character":{"c":"Game Term","d":"A character controlled by a player."},"Possession":{"c":"Rule","d":"Some effects let a creature or entity possess another creature, and the effect defines how. Protection from Evil and Good can prevent possession and Dispel Evil and Good can end it."},"Proficiency":{"c":"Rule","d":"If you are proficient with something, you add your [[Proficiency Bonus]] to D20 Tests that use it. A creature can be proficient in a skill, a saving throw, a weapon or a tool."},"Reach":{"c":"Rule","d":"A creature has a reach of 5 feet unless a rule says otherwise."},"Resistance":{"c":"Rule","d":"With Resistance to a damage type, damage of that type is halved against you (round down). It applies only once to a single instance of damage."},"Ritual":{"c":"Spellcasting","d":"If you have a spell with the Ritual tag prepared, you can cast it as a Ritual. That takes 10 minutes longer and uses no spell slot, so you can't cast it at a higher level."},"Round Down":{"c":"Rule","d":"When you divide or multiply a number, round down any fraction, even a half or more, unless a rule says to round up."},"Save":{"c":"Rule","d":"Another name for a [[Saving Throw]]."},"Shape-Shifting":{"c":"Rule","d":"When Wild Shape, Polymorph or a similar effect changes your shape, its description says what happens. Unless it says otherwise, ongoing effects on you, such as conditions, spells and curses, carry over between forms. You return to your true form if you die."},"Simultaneous Effects":{"c":"Rule","d":"If two or more things happen at the same time on a turn, the person whose turn it is, player or DM, picks the order."},"Skill":{"c":"Rule","d":"An area of specialization tied to an ability. If you are proficient in a skill, add your [[Proficiency Bonus]] to ability checks for it."},"Spell":{"c":"Spellcasting","d":"A [[Magical Effect]] with the traits described in the spells chapter."},"Spell Attack":{"c":"Spellcasting","d":"An attack roll made as part of a spell or another magical effect."},"Spellcasting Focus":{"c":"Spellcasting","d":"An object that stands in for a spell's Material components when those components have no listed cost and the spell doesn't consume them. Some classes can use specific kinds of focus."},"Sphere":{"c":"Area of Effect","d":"An area that spreads in all directions from a point of origin, out to a radius the effect gives. The origin is inside the area."},"Stable":{"c":"Rule","d":"A creature is Stable if it has 0 Hit Points but doesn't have to make [[Death Saving Throw]]s."},"Stat Block":{"c":"Rule","d":"The game statistics of a monster. After the name it lists Size, Creature Type, Alignment, AC, Initiative and HP (with Hit Point Dice in parentheses), Speed, ability scores with modifiers and saving throw modifiers, Skills, Resistances, Vulnerabilities, Immunities, Gear, Senses (including Passive Perception), Languages and CR. Then come Traits, Actions, Bonus Actions and Reactions. An attack entry says whether it is melee or ranged, gives the attack bonus and reach or range, and says what happens on a hit. An attack targets one creature unless the entry says otherwise."},"Swim Speed":{"c":"Movement","d":"Used instead of your Speed to swim without the extra movement cost of [[Swimming]]."},"Swimming":{"c":"Movement","d":"Each foot of movement costs 1 extra foot, or 2 extra in [[Difficult Terrain]]. A Swim Speed removes the extra cost. The DM may call for a DC 15 Strength (Athletics) check to move any distance in rough water."},"Target":{"c":"Rule","d":"The creature or object an attack roll targets, that an effect forces to make a saving throw, or that a spell or other phenomenon picks to receive its effects."},"Telepathy":{"c":"Rule","d":"A magical ability to communicate mentally with another creature within a stated range. Unless a rule says otherwise, the other creature doesn't need to share a language, but it must understand at least one language or be telepathic itself. The telepath doesn't need to see it and can start or end contact at any time with no action. Contact can't start, and breaks at once, if either creature is [[Incapacitated]]. It also breaks if the other creature leaves the range or the telepath contacts a different creature. A creature without telepathy can receive messages but can't start a conversation. Once one starts, it can reply mentally until the link ends."},"Teleportation":{"c":"Rule","d":"Magical transport. You vanish and reappear elsewhere instantly without crossing the space between. It uses no movement unless a rule says so and never provokes [[Opportunity Attack]]s. Everything you wear and carry goes with you, but a creature you touch does not unless the effect says so. If the destination is occupied or blocked by a solid obstacle, you appear in the nearest unoccupied space you choose. The effect says whether you must see the destination."},"Unoccupied Space":{"c":"Rule","d":"A space is unoccupied if no creature is in it and objects don't completely fill it."},"Vulnerability":{"c":"Rule","d":"With Vulnerability to a damage type, damage of that type is doubled against you. It applies only once to a single instance of damage."},"Weapon":{"c":"Rule","d":"An object in the Simple or Martial weapon category."},"Weapon Attack":{"c":"Rule","d":"An attack roll made with a weapon."}};
export const LIB={on:0,q:"",cat:"all",hist:[],cur:null,idx:null,res:[],lim:60,sel:0,scroll:0,tries:0};
export const LIB_CATS=[["spell","Spells","tab-spells"],["item","Magic Items","tab-inventory"],["gear","Equipment","item-weapon"],["feat","Feats","ui-feature"],["species","Species","tab-description"],["bg","Backgrounds","tab-notes"],["class","Classes","tab-features"],["sub","Subclasses","tab-features"],["feature","Features and Traits","ui-feature"],["opt","Class Options","ui-feature"],["creature","Creatures","creature"],["monster","Bestiary","creature"],["rule","Rules","ui-book"],["deity","Deities","tab-description"],["hazard","Traps and Hazards","ui-book"],["vehicle","Vehicles","ui-book"],["object","Objects","ui-book"],["table","Tables","ui-book"],["psionic","Psionics","ui-feature"],["disease","Diseases","ui-book"],["cult","Cults and Boons","ui-book"],["recipe","Recipes","ui-book"],["charopt","Character Options","ui-book"],["language","Languages","ui-book"],["facility","Bastion Facilities","ui-book"],["optfeat","Optional Features","ui-feature"],["book","Books and Adventures","ui-book"],["homebrew","Homebrew","ui-book"]];
