/* spells of books that are off: the rows sit in window.WX.src[].rows (the builder moves them into SPELLS only when the book is on). The Library lists them all as reference */
let LIB_XSP=null;
function libXsp(){ if(LIB_XSP) return LIB_XSP; const m={}, have={}; try{ SPELLS.forEach((r) =>{ have[r[0]]=1; }); (env.WX&&env.WX.src||[]).forEach((q) =>{ (q.rows||[]).forEach((r) =>{ if(r&&r[0]&&!have[r[0]]&&!m[r[0]]){ m[r[0]]=r; r.__bk=q.tag||q.id; } }); }); }catch(er){} return (LIB_XSP=m); }
/* items, gear, species and backgrounds of books that are off: window.WXI, WXG, WXSP, WXBG (by book id). Same row shapes as DMGI, GEAR, SPECIES, BACKGROUNDS */
let LIB_X={};
function libX(kind){ if(LIB_X[kind]) return LIB_X[kind]; const m={}, W=env[{i:"WXI",g:"WXG",s:"WXSP",b:"WXBG"}[kind]]||{}, tag={}; try{ (env.WX&&env.WX.src||[]).forEach((q) =>{ tag[q.id]=q.tag||q.id; });
    Object.keys(W).forEach((id) =>{ const v=W[id]; if(Array.isArray(v)) v.forEach((r) =>{ if(r&&r[0]&&!m[r[0]]) m[r[0]]={r:r,bk:tag[id]||id}; }); else if(v&&typeof v==="object") Object.keys(v).forEach((n) =>{ if(!m[n]) m[n]={r:v[n],bk:tag[id]||id}; }); }); }catch(er){} return (LIB_X[kind]=m); }
document.addEventListener("qrefs",() =>{ LIB_X={}; LIB_XS=null; });
/* subclasses of books that are off: window.WXS = [{cls,name,src,arr:[[level,feature,text]]}]. The builder adds them to CLASSES only when the book is on */
var LIB_XS=null;
function libXs(){ if(LIB_XS) return LIB_XS; const m={}, tag={}; try{ (env.WX&&env.WX.src||[]).forEach((q) =>{ tag[q.id]=q.tag||q.id; }); (env.WXS||[]).forEach((e) =>{ if(!e||!e.name||!e.arr||m[e.name]) return; const c=CLASSES[e.cls]; if(c&&c.subs&&c.subs[e.name]) return; m[e.name]={cls:e.cls,arr:e.arr,bk:tag[e.src]||e.src}; }); }catch(er){} return (LIB_XS=m); }
env.__wxSpRow=function(n){ return libXsp()[n]||null; };
document.addEventListener("qrefs",() =>{ LIB_XSP=null; });
let LIB_BK=null;
/* which book an entry comes from: rows from the reference data carry a source id, hidden-book data carries the book tag */
export function libBook(e){ try{ if(!LIB_BK){ LIB_BK={}; const T={}, nm={core:"2024 core",dmg:"DMG 2024",phb14:"PHB 2014",dmg14:"DMG 2014",mm14:"MM 2014",misc14:"2014 books"};
    libBookPart1(T); const L=env.QREFS||{};
    Object.keys(L).forEach((c) => libBookFn2(L, nm, T, c)); }
  const k2=e.c+"|"+e.k; if(LIB_BK[k2]) return LIB_BK[k2]; let m=null;
  if(e.c==="item") m=libX("i")[e.k]; else if(e.c==="gear") m=libX("g")[e.k]; else if(e.c==="species") m=libX("s")[e.k]; else if(e.c==="bg") m=libX("b")[e.k]; else if(e.c==="sub") m=libXs()[e.k]; else if(e.c==="feat") m=env.WXF_ALL&&env.WXF_ALL[e.k];
  if(!m&&e.c==="feature"){ const f=/^(cls|sub|sp):([^|]+)\|/.exec(e.k); if(f){ if(f[1]==="sub") m=libXs()[f[2]]; else if(f[1]==="sp") m=libX("s")[f[2]]; if(!m) return f[1]==="cls"?"PHB 2024":""; } }
  if(m) return String(m.bk||"").toUpperCase();
  /* the rest is the 2024 core data of the app */
  if(/\(2014\)/.test(e.k)) return "2014 edition";
  if(e.c==="item") return "DMG 2024"; if(/^(spell|class|species|bg|feat|sub|gear|feature|opt|creature)$/.test(e.c)) return "PHB 2024"; }catch(er){} return ""; }
function libBookPart1(T){ return ((env.WX&&env.WX.src||[]).forEach((q) => libBookFn1(T, q))); }
function libBookFn1(T, q){ T[q.id]=(q.tag||q.id); }
function libBookFn2(L, nm, T, c){ L[c].forEach((r) =>{ const k=c+"|"+r.n; if(r.s&&!LIB_BK[k]) LIB_BK[k]=nm[r.s]||String(T[r.s]||r.s).toUpperCase(); }); }
document.addEventListener("qrefs",() =>{ LIB_BK=null; });
