function libDetailRawPart12(c, k){ return (c==="species"&&(SPECIES[k]||(libX("s")[k]&&libX("s")[k].r))); }
function libDetailRawPart13(k){ return (SPECIES[k]||(libX("s")[k]&&libX("s")[k].r)); }
